/* Trigger structure for table `permission_access_tokens` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `access_tokens` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'localhost' */ /*!50003 TRIGGER `access_tokens` BEFORE UPDATE ON `permission_access_tokens` FOR EACH ROW BEGIN
	IF CURDATE() <= new.date THEN
		SET new.status = 'is_active';
	ELSE
		SET new.status = 'is_deactive';
	END IF;
    END */$$


DELIMITER ;

/* Procedure structure for procedure `setAutoIncrement` */

/*!50003 DROP PROCEDURE IF EXISTS  `setAutoIncrement` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `setAutoIncrement`(IN tableName VARCHAR(255), IN autoIncrementValue INT)
BEGIN
    SET @sql = CONCAT('ALTER TABLE ', tableName, ' AUTO_INCREMENT = ', autoIncrementValue);
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END */$$
DELIMITER ;

